#!/usr/bin/env python3
"""The in-core copy of InLean, generated by a fixed rule list.

`InLean/*` is con-leche's checker twin on `Lean.Expr`.  A copy of it lives
in a lean4 checkout at `src/Lean/Kernel/InLean/`; that copy is InLean up to
the mechanical renaming below and nothing else, so it is generated, and a
lean4 sync round checks it.

Usage (run with `python3 -I`):

  inlean-sync.py generate <out-dir>
      Write the core copy of `InLean/` (relative to this repository) into
      <out-dir>, which must not exist or be empty.
  inlean-sync.py check <lean4>/src/Lean/Kernel/InLean
      Regenerate into a temporary directory and compare it with the given
      copy.  The files in CORE_ONLY and the `pins/` data are not compared;
      every other file must be present on both sides and equal.  Exit 1 on
      any difference (a unified diff is printed), 0 otherwise.

The rules, applied to every `InLean/**/*.lean` file, in this order:

  1. Header.  The Lean copyright block (HEADER) goes in front.  The year is
     fixed (YEAR): every InLean file was created in 2026, and a fixed year
     keeps the copy independent of git history.
  2. `prelude`.  The file's first line is `module`, followed by one blank
     line; the generated copy has `module`, a blank line, `prelude`, the
     file's explicit Init imports (INIT_IMPORTS, data below: what a
     `prelude` module of lean4 must import that con-leche gets implicitly)
     and a blank line.
  3. Renaming.  `InLean` as a module or namespace prefix becomes
     `Lean.Kernel.InLean`: every `InLean` immediately followed by `.` and an
     identifier character (imports, qualified names, module citations in
     comments), and the operand of `namespace`/`end`/`open InLean`.  Other
     occurrences (`InLean:`, `InLean's`, the `(InLean)` message prefix) stay.
  4. The Nat-operation pin dumps.  `include_str "../pins/` becomes
     `include_str "pins/` (the copy keeps the dumps in its own `pins/`).

Nothing else changes: comments and docstrings are copied verbatim, so they
are written in InLean to read correctly in both places.
"""

import difflib
import os
import re
import sys
import tempfile

YEAR = 2026

HEADER = f"""/-
Copyright (c) {YEAR} Lean FRO, LLC. All rights reserved.
Released under Apache 2.0 license as described in the file LICENSE.
Authors: Joachim Breitner
-/
"""

# Per file (path relative to InLean/): the Init imports the lean4 copy adds
# after `prelude`.  A `prelude` module gets no implicit `Init`; a file that
# reaches Init only through `Lean.*` imports needs nothing here.
INIT_IMPORTS = {
    "ExprEq.lean": ["public import Init"],
}

# Files of the core copy that have no InLean source (the glue to lean4's
# kernel entry points).  `check` does not compare them.
CORE_ONLY = ["Core.lean"]

# Data directories of the core copy that `check` does not compare.
IGNORED_DIRS = ["pins"]

REPO = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SRC = os.path.join(REPO, "InLean")

RENAME_QUALIFIED = re.compile(r"(?<![A-Za-z0-9_.'])InLean(?=\.[A-Za-z_])")
RENAME_OPERAND = re.compile(r"^(\s*(?:namespace|end|open)\s+)InLean\b", re.M)
INCLUDE_PINS = 'include_str "../pins/'


class SyncError(Exception):
    pass


def source_files():
    out = []
    for root, dirs, files in os.walk(SRC):
        dirs.sort()
        for f in sorted(files):
            if f.endswith(".lean"):
                out.append(os.path.relpath(os.path.join(root, f), SRC))
    return sorted(out)


def transform(rel, text):
    if not text.startswith("module\n\n"):
        raise SyncError(f"{rel}: does not start with `module` and a blank line")
    body = text[len("module\n\n"):]
    head = "module\n\nprelude\n"
    for imp in INIT_IMPORTS.get(rel, []):
        head += imp + "\n"
    head += "\n"
    body = RENAME_QUALIFIED.sub("Lean.Kernel.InLean", body)
    body = RENAME_OPERAND.sub(r"\1Lean.Kernel.InLean", body)
    body = body.replace(INCLUDE_PINS, 'include_str "pins/')
    return HEADER + head + body


def generate(out):
    for k in INIT_IMPORTS:
        if not os.path.isfile(os.path.join(SRC, k)):
            raise SyncError(f"INIT_IMPORTS names {k}, which InLean does not have")
    if os.path.exists(out) and os.listdir(out):
        raise SyncError(f"{out}: exists and is not empty")
    files = source_files()
    for rel in files:
        with open(os.path.join(SRC, rel), encoding="utf-8") as fh:
            text = fh.read()
        dst = os.path.join(out, rel)
        os.makedirs(os.path.dirname(dst), exist_ok=True)
        with open(dst, "w", encoding="utf-8", newline="\n") as fh:
            fh.write(transform(rel, text))
    return files


def tree(d):
    out = set()
    for root, dirs, files in os.walk(d):
        rel_root = os.path.relpath(root, d)
        if rel_root != "." and rel_root.split(os.sep)[0] in IGNORED_DIRS:
            continue
        for f in files:
            rel = os.path.normpath(os.path.join(rel_root, f))
            if rel.split(os.sep)[0] in IGNORED_DIRS or rel in CORE_ONLY:
                continue
            out.add(rel)
        for sub in dirs:
            p = os.path.join(root, sub)
            rel = os.path.normpath(os.path.join(rel_root, sub))
            if rel.split(os.sep)[0] not in IGNORED_DIRS and not os.listdir(p):
                out.add(rel + os.sep)  # an empty directory is a difference
    return out


def check(copy):
    if not os.path.isdir(copy):
        raise SyncError(f"{copy}: not a directory")
    with tempfile.TemporaryDirectory() as tmp:
        gen = os.path.join(tmp, "InLean")
        generate(gen)
        a, b = tree(gen), tree(copy)
        bad = False
        for rel in sorted(a - b):
            print(f"missing in the copy: {rel}")
            bad = True
        for rel in sorted(b - a):
            print(f"only in the copy: {rel}")
            bad = True
        for rel in sorted(a & b):
            if rel.endswith(os.sep):
                continue
            with open(os.path.join(gen, rel), encoding="utf-8") as fh:
                x = fh.read().splitlines(keepends=True)
            with open(os.path.join(copy, rel), encoding="utf-8") as fh:
                y = fh.read().splitlines(keepends=True)
            if x != y:
                bad = True
                sys.stdout.writelines(difflib.unified_diff(
                    x, y, f"generated/{rel}", f"copy/{rel}"))
        print("inlean-sync check:", "DIFFERENT" if bad else "OK")
        return 1 if bad else 0


def main(argv):
    if len(argv) != 3 or argv[1] not in ("generate", "check"):
        print(__doc__.split("\n\n")[1], file=sys.stderr)
        print("usage: inlean-sync.py generate <out-dir> | check <copy-dir>",
              file=sys.stderr)
        return 2
    try:
        if argv[1] == "generate":
            generate(argv[2])
            return 0
        return check(argv[2])
    except SyncError as e:
        print(f"inlean-sync: {e}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    sys.exit(main(sys.argv))
